  'assistant.usageScopeConversation': '선택한 모델 또는 CLI가 보고한 이 대화의 AI 응답 사용량을 합산합니다. MonoField만의 추가 사용량을 뜻하지 않으며, 런타임 자체의 기본 지침·도구·대화 기록과 MonoField가 전달한 필요한 프로젝트 맥락을 함께 포함합니다. 브라우저·파일 탭을 새로 열어도 대화는 새로 시작되지 않습니다.',
  'assistant.usageScopeResponse': '이 값은 MonoField가 추가로 사용한 토큰이 아닙니다. 선택한 모델 또는 CLI가 이번 응답에 처리했다고 보고한 전체 입력으로, 런타임 자체의 기본 지침·도구·대화 기록과 MonoField가 전달한 필요한 프로젝트 맥락을 함께 포함합니다. 같은 짧은 질문을 해당 모델이나 CLI에 직접 입력해도 큰 기본 입력값이 표시될 수 있습니다.',
  'assistant.usageHintMeasured': '선택한 모델 제공자 또는 CLI 런타임이 보고한 전체 실행 값입니다.',
