  'assistant.usageCostUnavailableHint': '현재 제공자 또는 CLI가 이 실행의 USD 금액을 반환하지 않았습니다. 구독·크레딧 사용량과 API 키 과금은 서로 달라 MonoField가 임의의 API 비용으로 환산하지 않습니다.',
  'assistant.usageMethod': '단위 및 계산 기준',
  'assistant.usageTokenDefinition': '토큰은 글자나 단어 수가 아니라 모델의 토크나이저 단위입니다. 같은 문장도 모델에 따라 수가 달라질 수 있습니다.',
  'assistant.usageTotalDefinition': '전체는 제공자가 반환한 합계를 우선 사용하고, 없으면 입력 + 출력으로 계산합니다.',
  'assistant.usageCacheDefinition': '캐시 재사용은 전체 입력 중 제공자가 재사용했다고 보고한 분량입니다. 새 입력은 전체 입력에서 이를 뺀 값이며, 전체에는 한 번만 포함됩니다.',
  'assistant.usageReasoningDefinition': '추론은 제공자가 별도로 반환할 때만 표시합니다. 일반적으로 출력 또는 전체에 이미 포함되어 다시 더하지 않습니다.',
  'assistant.usageCostDefinition': 'USD는 제공자 또는 CLI가 이 실행의 과금 금액을 반환한 경우에만 표시합니다.',
  'assistant.usageContextDefinition': '첫 응답에도 모델·CLI의 기본 지침과 도구 스키마가 포함됩니다. 제공자 또는 CLI는 이 전체 입력을 합산해 보고하므로 MonoField가 전달한 추가 맥락만 정확히 분리해 표시할 수 없습니다. 새 대화의 캐시 입력은 이전 대화를 불러왔다는 뜻이 아니라 동일한 고정 접두부를 재사용했다는 뜻일 수 있습니다.',
